import * as Effect from "effect/Effect"

class NotFound { readonly _tag = "NotFound" }

// The name of the function that called it.
const frameName = (stack: string | undefined): string => {
  const line = (stack ?? "").split("\n")[1] ?? ""
  const m = /^\s*at (?:async )?(\S+) \(/.exec(line)
  return m ? m[1].slice(m[1].lastIndexOf(".") + 1) : ""
}

const step = (n: number): number!NotFound => n > 0 ? Effect.succeed(n) : Effect.fail(new NotFound())

// The recovery program is parenthesized, as alchemy writes it.
export const probe = () => do {
  const catchProgram = (effect {
    const v = try step(1)
    return frameName(new Error().stack) + ":" + v
  })
  effect {
    return catchProgram catch effect (e) => match (e) {
      when { _tag: "NotFound" }: "none";
      default: throw e;
    }
  }
}

